//! The design tokens of `tokens.json`, generated by `build.rs`.

/// The token set as CSS custom properties: light on `:root`, dark under
/// `prefers-color-scheme` and `[data-theme="dark"]`, the light values again under
/// `[data-theme="light"]` (after the dark media block, so a forced-light page beats a dark OS),
/// phone overrides under `max-width`.
pub const CSS: &str = include_str!(concat!(env!("OUT_DIR"), "/tokens.css"));

/// Every token value as a `&str` constant, named by its full path with the theme kept.
pub mod values {
    include!(concat!(env!("OUT_DIR"), "/tokens_values.rs"));
}
